"use client";

import { featuredProjects } from "../lib/projects";

/* Accent color per category — mirrors FilmSort's type-pill color system */
function getCategoryColor(category: string) {
  const map: Record<string, { color: string; label: string }> = {
    mobile:      { color: "#60a5fa", label: "Mobile"     },
    web:         { color: "#d4d4d8", label: "Web"        },
    "ai-tool":   { color: "#f87171", label: "AI Tool"    },
    "client-work":{ color: "#f59e0b", label: "Client"    },
    community:   { color: "#facc15", label: "Community"  },
    experiment:  { color: "#a78bfa", label: "Experiment" },
  };
  return map[category] ?? { color: "#a1a1aa", label: category };
}

